def solution():
    import math
    # Known 1‑year zero rate (continuous)
    r1 = 0.018
    # Bond cash‑flow details (2‑year semi‑annual coupon bond)
    price = 101.5               # dirty price (settlement on a coupon date → no accrued interest)
    coupon_rate = 0.03          # annual coupon
    cf = coupon_rate / 2 * 100  # each semi‑annual payment
    # Present value of cash flows that fall before the 2‑year horizon using the 1‑year zero
    def df(t, r):
        return math.exp(-r * t)
    pv_first_two = cf * df(0.5, r1) + cf * df(1.0, r1)
    # Remaining cash flows at 1.5 and 2.0 years are discounted with the unknown 2‑year zero rate r2
    def residual(r2):
        return (
            cf * df(1.5, r2) +
            (cf + 100) * df(2.0, r2) +
            pv_first_two -
            price
        )
    # Simple bisection to solve for r2 (continuous)
    low, high = 0.0, 0.10  # plausible bounds for a 2‑year rate
    for _ in range(100):
        mid = (low + high) / 2.0
        if residual(mid) > 0:
            low = mid
        else:
            high = mid
    r2 = (low + high) / 2.0
    return r2

