def solution():
    import math
    # Cash‑flow schedule for the pension plan
    cfs = {
        1: 1_200_000,
        2: 1_400_000,
        3: 1_600_000,
        4: 1_800_000,
        5: 2_000_000,
        6: 2_200_000,
        7: 2_400_000,
    }
    # Given zero‑coupon yields (continuously compounded) at specific maturities
    yields = {
        2: 0.020,
        5: 0.025,
        7: 0.028,
    }

    # Helper to linearly interpolate the continuously‑compounded rate for any year t
    def interp_rate(t):
        # Find surrounding maturities
        sorted_mats = sorted(yields.keys())
        if t <= sorted_mats[0]:
            return yields[sorted_mats[0]]
        if t >= sorted_mats[-1]:
            return yields[sorted_mats[-1]]
        for i in range(1, len(sorted_mats)):
            t0, t1 = sorted_mats[i-1], sorted_mats[i]
            if t0 <= t <= t1:
                r0, r1 = yields[t0], yields[t1]
                # Linear interpolation on the rate (not on discount factor)
                return r0 + (r1 - r0) * (t - t0) / (t1 - t0)
        # Fallback (should not happen)
        return yields[sorted_mats[-1]]

    pv = 0.0
    for t, cf in cfs.items():
        r = interp_rate(t)
        discount_factor = math.exp(-r * t)
        pv += cf * discount_factor
    # Round to nearest dollar as required
    return round(pv)

