    import math
    # Helper to compute annual continuously‑compounded risk‑free rate from semi‑annual zero‑coupon price
    def rf_from_price(price):
        # price = 100 / (1 + y/2)^2  => y = 2*((100/price)^(1/2) - 1)
        return 2 * ((100.0 / price) ** 0.5 - 1)

    years = [2023, 2024, 2025]
    fund_ret = {2023: 0.124, 2024: 0.087, 2025: 0.153}
    beta = {2023: 0.95, 2024: 1.02, 2025: 0.88}
    price = {2023: 98.50, 2024: 97.30, 2025: 96.10}
    market_ret = {2023: 0.102, 2024: 0.115, 2025: 0.098}

    alphas = []
    for yr in years:
        r_f = rf_from_price(price[yr])
        expected = r_f + beta[yr] * (market_ret[yr] - r_f)
        alpha = fund_ret[yr] - expected
        alphas.append(alpha)

    # Geometric mean of (1 + alpha)
    prod = 1.0
    for a in alphas:
        prod *= (1 + a)
    geo_mean = prod ** (1.0 / len(alphas)) - 1
    return geo_mean

