            rate = spot
        else:
            rate = spot + forward_points[t] * 0.0001
        cf_usd.append(cf * rate)
    # Define NPV function for a given discount rate r (annual, compounded annually)
    def npv(r):
        return sum(cf_usd[i] / ((1 + r) ** i) for i in range(len(cf_usd)))
    # Newton‑Raphson to solve npv(r)=0
    r = 0.09  # initial guess
    for _ in range(100):
        f = npv(r)
        eps = 1e-8
        f_prime = (npv(r + eps) - f) / eps
        r_new = r - f / f_prime
        if abs(r_new - r) < 1e-12:
            break
        r = r_new
    return r
